import {LEVELS,RECIPES,MATCH_STEPS,startState,newLeaguePolicy,leagueRollout,leagueEvaluation,parseLeagueVote,validateLeaguePolicy,stepLeague} from './league.js';
import {MedusaScene} from './medusa-scene.js';
import {CoachClash} from './clash-ui.js';
import {createVoyageUI,voyageIcon} from './voyage-ui.js';
import {TwitchChat,authorizationUrl} from './twitch.js';
const $=id=>document.getElementById(id),gsap=window.gsap,rules=['goal','touch','progress','safety'],overlay=new URLSearchParams(location.search).has('overlay'),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(overlay)document.body.classList.add('overlay');
createVoyageUI();
let clash=null;
let level=LEVELS[0],policies={},stars={},current=null,worker=null,frames=[],frameIndex=0,paused=false,lastStep=0,mode='rookie',manualState=null,lastManual=0,scene=null,votes=new Map(),voteEnd=0,voteTimer=null,sound=false,audio=null,toastTimer;
let unloading=false;function broadcast(data){if(!unloading)sync?.postMessage(data);}
const sync=typeof BroadcastChannel==='function'?new BroadcastChannel('medusa-league'):null;
try{const saved=JSON.parse(localStorage.getItem('medusa-league-v1'));if(saved?.version===1){for(const l of LEVELS){if(validateLeaguePolicy(saved.policies?.[l.id],l))policies[l.id]=saved.policies[l.id];if(Number.isInteger(saved.stars?.[l.id]))stars[l.id]=Math.max(0,Math.min(3,saved.stars[l.id]));}}}catch{}
const weights=()=>Object.fromEntries(rules.map(k=>[k,Number($(k).value)]));
function setWeights(w){for(const k of rules){$(k).value=w[k];$(k+'-value').value=(k==='safety'?'−':'+')+w[k];}const balanced=JSON.stringify(w)===JSON.stringify(RECIPES.balanced);$('recipe-balanced').classList.toggle('active',balanced);$('recipe-chaos').classList.toggle('active',!balanced&&w.touch>=3);}
function toast(text){$('toast').textContent=text;clearTimeout(toastTimer);gsap.to('#toast',{y:0,autoAlpha:1,duration:reduced?0:.3});toastTimer=setTimeout(()=>gsap.to('#toast',{y:70,autoAlpha:0,duration:.3}),3500);}
function save(){try{localStorage.setItem('medusa-league-v1',JSON.stringify({version:1,policies,stars}));}catch{toast('Your browser could not save league progress. Export the experiment to keep it.');}}
function snapshot(){if(!overlay)broadcast({type:'snapshot',levelId:level.id,current,mode,stars});}
function worldIcon(l){if(l.theme)return voyageIcon(l);const blocks=l.id==='reef'?'<path d="M33 19v20m6-22v20" stroke="#ffb98a" stroke-width="5"/>':l.id==='current'?'<path d="m23 24 8 4-8 4m12-12 8 4-8 4" fill="none" stroke="#b7adff" stroke-width="2"/>':l.id==='abyss'?'<circle cx="37" cy="24" r="6" fill="#ff8ed8"/>':'';return `<svg class="world-icon" viewBox="0 0 75 58" aria-hidden="true"><path d="m6 28 33-17 31 17-33 18Z" fill="#112634" stroke="${l.color}" stroke-opacity=".7"/><path d="m6 28v7l31 18 33-18v-7L37 46Z" fill="#213543"/><path d="m13 29 25-13 23 13-25 13Z" fill="${l.color}" fill-opacity=".09"/><path d="M39 17 36 42M20 24l23 13" stroke="${l.color}" stroke-opacity=".25"/>${blocks}<circle cx="24" cy="29" r="3" fill="${l.color}"/></svg>`;}
function renderWorlds(){$('arenas').innerHTML=LEVELS.map(l=>`<button class="world-card ${l.id===level.id?'active':''}" data-level="${l.id}" style="--world-color:${l.color}" aria-pressed="${l.id===level.id}">${worldIcon(l)}<div><span class="world-number">ARENA ${l.number}</span><h3>${l.name}</h3><p>${l.tag}</p></div><span class="stars">${'✦'.repeat(stars[l.id]||0)}</span></button>`).join('');for(const button of $('arenas').querySelectorAll('button'))button.onclick=()=>selectLevel(button.dataset.level);}
function setBusy(busy){for(const id of ['train','recipe-balanced','recipe-chaos','rookie','manual','vote-open'])$(id).disabled=busy;for(const k of rules)$(k).disabled=busy;$('train').firstChild.textContent=busy?'Learning… ':'Train Medusa ';}
function selectLevel(id){const next=LEVELS.find(l=>l.id===id);if(!next)return;clash?.cancel(false);if(worker){worker.terminate();worker=null;setBusy(false);}closeVotes(false);level=next;current=policies[id]||null;mode=current?'trained':'rookie';setWeights(current?.weights||RECIPES.balanced);$('arena-index').textContent=level.number+' / '+level.world;$('arena-title').textContent=level.name;$('level-description').textContent=level.description;$('goal-target').textContent=String(level.target).padStart(2,'0');$('progress-bar').value=current?10000:0;$('training-status').textContent=current?'Saved policy restored · 10,000 episodes · seed 42':'10,000 episodes · runs on your device';$('manual-pad').hidden=true;$('manual').textContent='Play yourself ↗';$('scene-hint').textContent='DRAG TO ORBIT · SCROLL TO ZOOM';scene?.load(level);clash?.showtime?.updateArena();renderWorlds();updateEvaluation();replay();snapshot();}
function updateEvaluation(){const w=current?.weights||weights(),q=current?.q||newLeaguePolicy(level),rookie=leagueEvaluation(q,w,level,{randomPolicy:true});$('rookie-average').textContent=rookie.goals.toFixed(1);$('rookie-bar').style.width=Math.max(2,Math.min(100,rookie.goals/20*100))+'%';if(current){const trained=leagueEvaluation(q,w,level);$('trained-average').textContent=trained.goals.toFixed(1);$('trained-bar').style.width=Math.min(100,trained.goals/20*100)+'%';$('improvement').textContent=`+${(trained.goals-rookie.goals).toFixed(1)} goals per match`;$('evaluation-note').textContent='Same arena, recipe, and 120-move limit. Rookie uses 5 seeded random runs; trained policy acts greedily.';}else{$('trained-average').textContent='—';$('trained-bar').style.width='0%';$('improvement').textContent='Ready to learn.';$('evaluation-note').textContent='Train a policy to compare against seeded random play on this arena.';}drawChart(current?.history||[]);}
function drawChart(history){const canvas=$('learning-chart'),c=canvas.getContext('2d'),w=canvas.width,h=canvas.height;c.clearRect(0,0,w,h);const max=Math.max(20,...history.map(p=>p.goals));c.strokeStyle='#203047';c.lineWidth=1;for(let y=20;y<=100;y+=40){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke();}if(!history.length){c.fillStyle='#607a91';c.font='13px sans-serif';c.fillText('Your learning curve starts here.',12,64);return;}c.beginPath();c.moveTo(0,h);for(const point of history)c.lineTo(point.episode/10000*w,h-10-point.goals/max*(h-25));c.lineTo(w,h);c.closePath();const gradient=c.createLinearGradient(0,0,0,h);gradient.addColorStop(0,'#75f7d433');gradient.addColorStop(1,'#75f7d400');c.fillStyle=gradient;c.fill();c.strokeStyle='#75f7d4';c.lineWidth=2.5;c.beginPath();history.forEach((p,i)=>{const x=p.episode/10000*w,y=h-10-p.goals/max*(h-25);if(i)c.lineTo(x,y);else c.moveTo(x,y);});c.stroke();}
function replay(){const w=current?.weights||weights(),q=current?.q||newLeaguePolicy(level);frames=leagueRollout(q,w,level,{randomPolicy:mode==='rookie'}).frames;frameIndex=0;paused=false;lastStep=performance.now();$('match-result').hidden=true;$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','Pause match');$('policy-badge').textContent=mode==='manual'?'HUMAN COACH':mode==='trained'?'TRAINED POLICY':'ROOKIE POLICY';$('recipe-name').textContent=mode==='trained'?'Trained':mode==='manual'?'Human':'Rookie';$('episode-count').textContent=mode==='trained'?'10,000 episodes · seed 42':'Untrained · seeded random actions';scene?.setPlaying(true);updateFrame(frames[0],true);}
function updateFrame(entry,immediate=false){const s=entry.state;$('goals').textContent=s.goals;$('collisions').textContent=s.collisions;$('reward').textContent=s.reward.toFixed(1);$('goals-hud').textContent=String(s.goals).padStart(2,'0');$('match-clock').textContent=String(s.t).padStart(2,'0')+' / 120 MOVES';$('action-label').textContent=entry.event;scene?.setFrame(entry,Number($('speed').value)/1000,immediate);if(entry.kind==='goal'&&!immediate){celebrate();}if(!overlay)broadcast({type:'frame',levelId:level.id,entry,immediate});}
function celebrate(){gsap.killTweensOf('#celebration');gsap.fromTo('#celebration',{autoAlpha:0,scale:.75},{autoAlpha:1,scale:1,duration:reduced?0:.25,ease:'back.out(1.8)',onComplete:()=>gsap.to('#celebration',{autoAlpha:0,delay:.35,duration:.25})});if(sound){for(const [i,f] of [523.25,659.25,783.99].entries()){const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.value=f;gain.gain.setValueAtTime(.025,audio.currentTime+i*.06);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.45+i*.06);oscillator.connect(gain).connect(audio.destination);oscillator.start(audio.currentTime+i*.06);oscillator.stop(audio.currentTime+.5+i*.06);}}}
function finish(){paused=true;scene?.setPlaying(false);$('pause').textContent='▶';$('pause').setAttribute('aria-label','Play match');const s=(mode==='manual'?manualState:frames[frames.length-1].state),earned=Math.min(3,Math.floor(s.goals/level.target*3));if(mode==='trained'){stars[level.id]=Math.max(stars[level.id]||0,earned);save();renderWorlds();}const win=s.goals>=level.target;$('result-title').textContent=win?'A legend in the making.':'Every legend starts somewhere.';$('result-stars').textContent='✦'.repeat(earned)+'☆'.repeat(3-earned);$('result-copy').textContent=`${s.goals} goals in 120 moves. ${win?'Arena target cleared. Try the next world.':mode==='rookie'?'This is untrained play. Give Medusa a reason to score.':'Try the goal-getter recipe, train again, and chase the target.'}`;$('match-result').hidden=false;$('next-level').textContent=level.id===LEVELS.at(-1).id?'Back to the lagoon →':'Next arena →';if(!reduced)gsap.from('#match-result',{y:12,opacity:0,duration:.4});snapshot();}
function train(){if(worker||overlay)return;closeVotes(false);mode='trained';$('manual-pad').hidden=true;setBusy(true);$('match-result').hidden=true;$('policy-badge').textContent='LEARNING…';$('progress-bar').value=0;const requestedLevel=level.id,requestedWeights=weights();worker=new Worker('./league-worker.js',{type:'module'});worker.onmessage=({data})=>{if(requestedLevel!==level.id)return;if(data.type==='progress'){$('progress-bar').value=data.episode;$('training-status').textContent=`${data.episode.toLocaleString()} / 10,000 episodes · ${data.metrics.goals.toFixed(1)} goals / match`;}
 if(data.type==='complete'){current={q:data.q,weights:data.weights,levelId:data.levelId,seed:data.seed,total:data.total,history:data.history};policies[level.id]=current;worker.terminate();worker=null;setBusy(false);$('training-status').textContent='10,000 episodes complete · frozen replay · seed 42';updateEvaluation();save();replay();snapshot();toast('Training complete. Watch what your incentives taught her.');}if(data.type==='error'){worker.terminate();worker=null;setBusy(false);toast(data.message);}};worker.onerror=()=>{worker.terminate();worker=null;setBusy(false);$('training-status').textContent='Training could not start. Retry or use Classic Café.';};worker.postMessage({levelId:level.id,weights:requestedWeights,seed:42,total:10000});}
function advanceSolo(now){if(mode==='manual'||paused||worker||now-lastStep<Number($('speed').value))return;lastStep=now;if(frameIndex<frames.length-1){frameIndex++;updateFrame(frames[frameIndex]);}else finish();}
let lastOverlayTick=0;
function tick(now){requestAnimationFrame(tick);if(overlay){if(!clash?.active()&&now-lastOverlayTick>75){lastOverlayTick=now;broadcast({type:'tick'});}return;}if(!document.hidden)advanceSolo(now);}requestAnimationFrame(tick);
for(const k of rules)$(k).oninput=()=>{$(k+'-value').value=(k==='safety'?'−':'+')+$(k).value;$('recipe-balanced').classList.remove('active');$('recipe-chaos').classList.remove('active');$('training-status').textContent='Recipe edited. Train to apply; this replay keeps its saved recipe.';};
$('recipe-balanced').onclick=()=>{setWeights(RECIPES.balanced);$('training-status').textContent='Goal-getter recipe ready. Train Medusa to apply.';};$('recipe-chaos').onclick=()=>{setWeights(RECIPES.chaos);$('training-status').textContent='Chaos recipe ready. Will she chase touches instead of goals?';};$('train').onclick=train;
$('rookie').onclick=()=>{mode='rookie';$('manual-pad').hidden=true;replay();snapshot();};$('replay').onclick=()=>{if(mode==='manual')startManual();else replay();snapshot();};$('result-replay').onclick=()=>$('replay').click();$('pause').onclick=()=>{if(mode==='manual')return;if(frameIndex>=frames.length-1){replay();return;}paused=!paused;scene?.setPlaying(!paused);$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Play match':'Pause match');};$('next-level').onclick=()=>selectLevel(LEVELS[(LEVELS.indexOf(level)+1)%LEVELS.length].id);
function startManual(){mode='manual';paused=false;manualState=startState(level);$('manual-pad').hidden=false;$('manual').textContent='Back to AI ↗';$('match-result').hidden=true;$('policy-badge').textContent='HUMAN COACH';$('scene-hint').textContent='WASD / ARROWS TO DRIBBLE · SPACE TO WAIT';$('recipe-name').textContent='Human';$('episode-count').textContent='You control every decision';scene?.setPlaying(true);updateFrame({state:manualState,event:'Your turn. Arrow keys move the ball.',kind:'start'},true);}
function manualAction(action){if(mode!=='manual'||manualState.t>=MATCH_STEPS||performance.now()-lastManual<150)return;lastManual=performance.now();const next=stepLeague(manualState,action,weights(),level);manualState=next.state;updateFrame(next);if(next.terminal){manualState={...manualState,x:level.spawn[0],y:level.spawn[1]};}if(manualState.t>=MATCH_STEPS)finish();}
$('manual').onclick=()=>{if(mode==='manual'){mode=current?'trained':'rookie';$('manual-pad').hidden=true;$('manual').textContent='Play yourself ↗';$('scene-hint').textContent='DRAG TO ORBIT · SCROLL TO ZOOM';replay();}else startManual();};for(const button of document.querySelectorAll('[data-action]'))button.onclick=()=>manualAction(Number(button.dataset.action));window.addEventListener('keydown',event=>{if(mode!=='manual'||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)||$('twitch-dialog').open)return;const key={ArrowUp:0,w:0,ArrowRight:1,d:1,ArrowDown:2,s:2,ArrowLeft:3,a:3,' ':4}[event.key];if(key!==undefined){event.preventDefault();manualAction(key);}});
for(const view of ['iso','top','follow'])$('camera-'+view).onclick=()=>{scene?.view(view);for(const k of ['iso','top','follow'])$('camera-'+k).classList.toggle('active',view===k);};$('sound').onclick=()=>{sound=!sound;if(sound){audio ||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();}$('sound').classList.toggle('active',sound);$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');toast(sound?'Goal celebrations: sound on':'Sound off');};$('fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('viewport').requestFullscreen?.().catch(()=>toast('Fullscreen is not available here.'));};
function openVotes(){votes=new Map();voteEnd=Date.now()+30000;$('vote-open').textContent='Close & apply';voteTimer=setInterval(()=>{if(Date.now()>=voteEnd)closeVotes();else $('vote-status').textContent=`${Math.ceil((voteEnd-Date.now())/1000)}s left · ${votes.size} votes · one latest choice per viewer`;},250);$('vote-status').textContent='30s left. Chat is the coach.';}
function closeVotes(apply=true){if(!voteEnd)return;clearInterval(voteTimer);voteEnd=0;$('vote-open').textContent='Open 30-second vote ↗';if(apply&&votes.size){const next=weights();for(const rule of rules){const counts=new Map();for(const vote of votes.values())if(vote.rule===rule)counts.set(vote.value,(counts.get(vote.value)||0)+1);if(counts.size)next[rule]=[...counts].sort((a,b)=>b[1]-a[1]||a[0]-b[0])[0][0];}setWeights(next);$('vote-status').textContent=`Applied ${votes.size} votes. Ties choose the lower value. Train to apply.`;$('training-status').textContent='Chat recipe ready. Train Medusa to apply.';}else $('vote-status').textContent='Voting closed. No recipe changes.';}
function chatMessage(message){if(clash?.handleChat(message))return;const vote=parseLeagueVote(message.text);if(!vote||!voteEnd||Date.now()>=voteEnd||worker)return;votes.set(message.user,vote);$('chat-count').textContent=votes.size+' VOTES';$('vote-status').textContent=`Accepted ${vote.rule} ${vote.value} · ${votes.size} votes · ${message.name||'local test'}`;}
$('vote-open').onclick=()=>voteEnd?closeVotes():openVotes();$('vote-demo').onclick=()=>{if(worker)return;if(!voteEnd)openVotes();chatMessage({user:'local-demo',name:'LOCAL TEST',text:'!reward goal 10'});};
$('export').onclick=()=>{if(!current){toast('Train a policy before exporting.');return;}const data={version:1,game:'Medusa Reward League',level,policy:current,algorithm:{name:'Q-learning',alpha:.2,gamma:.95,episodes:10000,epsilon:'.95 decays to .045',observation:'ball grid position + observable world phase',actions:'north, east, south, west, wait'},evaluation:{rookie:leagueEvaluation(current.q,current.weights,level,{randomPolicy:true}),trained:leagueEvaluation(current.q,current.weights,level)},note:'3D animation visualizes a discrete tactical simulator. No claim of continuous-physics learning.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='medusa-'+level.id+'-experiment.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('reset-progress').onclick=()=>{policies={};stars={};save();selectLevel(level.id);toast('League progress reset. The classic café experiment is unchanged.');};
try{scene=new MedusaScene($('scene'));}catch(error){$('renderer-error').hidden=false;$('scene-status').textContent='3D UNAVAILABLE';console.error('WebGL initialization failed',error.message);}selectLevel(level.id);
clash=new CoachClash({getLevel:()=>level,setLevel:selectLevel,getScene:()=>scene,onStart:()=>{if(worker){worker.terminate();worker=null;}closeVotes(false);paused=true;setBusy(true);$('match-result').hidden=true;scene?.setPlaying(false);$('scene-status').textContent='COACH CLASH';},onEnd:restore=>{setBusy(false);$('scene-status').textContent='LIVE SIMULATION';if(restore){replay();snapshot();}},onGoal:()=>{if(sound){const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=659.25;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.35);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.4);}}});
if(!reduced)gsap.fromTo('.hero > div, .world-card',{y:15,opacity:0},{y:0,opacity:1,stagger:.07,duration:.7,ease:'power3.out'});
if(sync)sync.onmessage=({data})=>{if(overlay&&clash?.active())return;if(data.type==='tick'&&!overlay)advanceSolo(performance.now());if(data.type==='request'&&!overlay){snapshot();updateFrame(frames[frameIndex],true);}if(overlay&&data.type==='snapshot'){if(data.current&&validateLeaguePolicy(data.current,LEVELS.find(l=>l.id===data.levelId)||level))policies[data.levelId]=data.current;stars=data.stars||{};if(level.id!==data.levelId||current!==data.current){selectLevel(data.levelId);current=data.current;mode=data.mode;}}if(overlay&&data.type==='frame'){if(data.levelId!==level.id)selectLevel(data.levelId);$('match-result').hidden=true;updateFrame(data.entry,data.immediate);}};if(overlay)broadcast({type:'request'});
const redirect=location.origin+(location.pathname.endsWith('league.html')?'/':location.pathname);$('redirect-url').textContent=redirect;$('client-id').value=sessionStorage.getItem('twitch-client')||'';$('channel-name').value=sessionStorage.getItem('twitch-channel')||'abhigamestalk';
const twitch=new TwitchChat(chatMessage,(status,error=false)=>{$('connection').textContent=status;$('twitch-open').style.borderColor=error?'#a36b6b':'#4b8e81';if(error)$('twitch-error').textContent=status;});$('twitch-open').onclick=()=>$('twitch-dialog').showModal();$('twitch-close').onclick=()=>$('twitch-dialog').close();$('twitch-disconnect').onclick=()=>{twitch.disconnect();$('connection').textContent='Connect Twitch';$('twitch-dialog').close();};
$('twitch-form').onsubmit=event=>{event.preventDefault();const client=$('client-id').value.trim(),name=$('channel-name').value.trim().toLowerCase(),state=crypto.randomUUID();sessionStorage.setItem('twitch-state',state);sessionStorage.setItem('twitch-client',client);sessionStorage.setItem('twitch-channel',name);location.href=authorizationUrl(client,redirect,state);};
const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')||fragment.has('error')){history.replaceState(null,'',location.pathname+location.search);const expected=sessionStorage.getItem('twitch-state');sessionStorage.removeItem('twitch-state');if(!expected||fragment.get('state')!==expected){$('twitch-error').textContent='Authorization state mismatch. Connect again.';$('twitch-dialog').showModal();}else if(fragment.has('error')){$('twitch-error').textContent=fragment.get('error_description')||'Authorization cancelled.';$('twitch-dialog').showModal();}else twitch.connect({token:fragment.get('access_token'),clientId:$('client-id').value,channel:$('channel-name').value}).catch(error=>{$('twitch-error').textContent=error.message;$('twitch-dialog').showModal();});}
window.addEventListener('beforeunload',()=>{unloading=true;worker?.terminate();twitch.disconnect();sync?.close();});
